#include <zephyr/syscalls/led.h>

#if defined(ZEPHYR_TESTSUITE_INCLUDE_ZTEST_H_) && DT_HAS_COMPAT_STATUS_OKAY(zephyr_fake_led)

#define DT_DRV_COMPAT zephyr_fake_led

struct z_led_fake_config {
	uint8_t num_leds;
	const struct led_info *leds_info;
};

#define Z_LED_FAKE_COLOR_MAPPING(led_node_id)                                                      \
	IF_ENABLED(DT_NODE_HAS_PROP(led_node_id, color_mapping),                                   \
		   (static const uint8_t z_led_fake_color_mapping_##led_node_id[] =                \
			    DT_PROP(led_node_id, color_mapping);))

#define Z_LED_FAKE_INFO_COLOR(led_node_id)                                                         \
	{                                                                                          \
		.label = DT_PROP_OR(led_node_id, label, NULL),                                     \
		.index = DT_PROP_OR(led_node_id, index, 0),                                        \
		.num_colors = DT_PROP_LEN(led_node_id, color_mapping),                             \
		.color_mapping = z_led_fake_color_mapping_##led_node_id,                           \
	},

#define Z_LED_FAKE_INFO_NO_COLOR(led_node_id)                                                      \
	{                                                                                          \
		.label = DT_PROP_OR(led_node_id, label, NULL),                                     \
		.index = DT_PROP_OR(led_node_id, index, 0),                                        \
		.num_colors = 0,                                                                   \
		.color_mapping = NULL,                                                             \
	},

#define Z_LED_FAKE_INFO(led_node_id)                                                               \
	COND_CODE_1(DT_NODE_HAS_PROP(led_node_id, color_mapping),                                  \
		    (Z_LED_FAKE_INFO_COLOR(led_node_id)),                                          \
		    (Z_LED_FAKE_INFO_NO_COLOR(led_node_id)))

static int z_led_fake_on(const struct device *dev, uint32_t led)
{
	const struct z_led_fake_config *config = dev->config;

	if (led >= config->num_leds) {
		return -EINVAL;
	}

	return 0;
}

static int z_led_fake_off(const struct device *dev, uint32_t led)
{
	const struct z_led_fake_config *config = dev->config;

	if (led >= config->num_leds) {
		return -EINVAL;
	}

	return 0;
}

static int z_led_fake_set_brightness(const struct device *dev, uint32_t led, uint8_t value)
{
	const struct z_led_fake_config *config = dev->config;

	ARG_UNUSED(value);

	if (led >= config->num_leds) {
		return -EINVAL;
	}

	return 0;
}

static int z_led_fake_get_info(const struct device *dev, uint32_t led,
			       const struct led_info **info)
{
	const struct z_led_fake_config *config = dev->config;

	if (led >= config->num_leds) {
		return -EINVAL;
	}

	*info = &config->leds_info[led];

	return 0;
}

static int z_led_fake_set_color(const struct device *dev, uint32_t led,
				uint8_t num_colors, const uint8_t *color)
{
	const struct z_led_fake_config *config = dev->config;

	ARG_UNUSED(color);

	if (led >= config->num_leds) {
		return -EINVAL;
	}

	if (config->leds_info[led].num_colors == 0) {
		return -ENOTSUP;
	}

	if (num_colors != config->leds_info[led].num_colors) {
		return -EINVAL;
	}

	return 0;
}

static DEVICE_API(led, z_led_fake_driver_api) = {
	.on = z_led_fake_on,
	.off = z_led_fake_off,
	.set_brightness = z_led_fake_set_brightness,
	.get_info = z_led_fake_get_info,
	.set_color = z_led_fake_set_color,
};

#define Z_LED_FAKE_INIT(inst)                                                                      \
	DT_INST_FOREACH_CHILD(inst, Z_LED_FAKE_COLOR_MAPPING)                                      \
                                                                                                   \
	static const struct led_info z_led_fake_info_##inst[] = {                                  \
		DT_INST_FOREACH_CHILD(inst, Z_LED_FAKE_INFO)                                       \
	};                                                                                         \
                                                                                                   \
	static const struct z_led_fake_config z_led_fake_config_##inst = {                         \
		.num_leds = ARRAY_SIZE(z_led_fake_info_##inst),                                    \
		.leds_info = z_led_fake_info_##inst,                                               \
	};                                                                                         \
                                                                                                   \
	DEVICE_DT_INST_DEFINE(inst, NULL, NULL, NULL, &z_led_fake_config_##inst, POST_KERNEL,      \
			      CONFIG_LED_INIT_PRIORITY, &z_led_fake_driver_api);

DT_INST_FOREACH_STATUS_OKAY(Z_LED_FAKE_INIT)

#undef DT_DRV_COMPAT

#endif /* defined(ZEPHYR_TESTSUITE_INCLUDE_ZTEST_H_) && DT_HAS_COMPAT_STATUS_OKAY(zephyr_fake_led) */

#endif	/* ZEPHYR_INCLUDE_DRIVERS_LED_H_ */
